{
position p, tmp;
/*1*/        p = L->next;   /* header assumed */
/*2*/        L->next = NULL;
/*3*/        while( p != NULL )
{
/*4*/             tmp = p->next;
/*5*/             free( p );
/*6*/             p = tmp;
}
}
