void
m_sort( input_type a[], input_type tmp_array[ ],
int left, int right )
{
int center;
if( left < right )
{
center = (left + right) / 2;
m_sort( a, tmp_array, left, center );

m_sort( a, tmp_array, center+1, right );
merge( a, tmp_array, left, center+1, right );
